import{_ as a,o as e,c as i,a5 as r}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"UC — Track Livestream Status","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-24-track-livestream-status/spec.md","filePath":"feature/content-task-workflow/3-6-24-track-livestream-status/spec.md"}'),n={name:"feature/content-task-workflow/3-6-24-track-livestream-status/spec.md"};function o(s,t,c,h,l,d){return e(),i("div",null,[...t[0]||(t[0]=[r(`<h1 id="uc-—-track-livestream-status" tabindex="-1">UC — Track Livestream Status <a class="header-anchor" href="#uc-—-track-livestream-status" aria-label="Permalink to &quot;UC — Track Livestream Status&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.6.24</td></tr><tr><td>Feature</td><td>Track Livestream Status</td></tr><tr><td>Domain</td><td>Content &amp; Workflow (FR 3.6)</td></tr><tr><td>Role</td><td>CREATOR</td></tr><tr><td>Version</td><td>2.0 (V2 — nghiệp vụ mới, 2026-09-14)</td></tr><tr><td>Trạng thái tài liệu</td><td>Draft — BA confirmed, chưa code</td></tr></tbody></table><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Hiển thị tiến độ Livestream theo các trạng thái Pre-live → Live → Post-live → Done/Cancel.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>Là một Creator, tôi muốn cập nhật trạng thái buổi livestream, để team theo dõi tiến độ thực tế của buổi live.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ul><li>4 trạng thái chính: <code>PRE_LIVE → LIVE → POST_LIVE → DONE</code>, có thể <code>CANCEL</code> ở PRE_LIVE hoặc LIVE.</li><li>Xem chi tiết transition tại <a href="./../../../BA/12-state-machines.html">12-state-machines.md</a> mục 5.</li><li>State này lồng bên trong Task cha — Task cha vẫn đi qua Approval Sequence (FR 3.6.9) sau khi Livestream state đạt DONE.</li></ul><h2 id="_4-ui-ux" tabindex="-1">4. UI / UX <a class="header-anchor" href="#_4-ui-ux" aria-label="Permalink to &quot;4. UI / UX&quot;">​</a></h2><ul><li>Progress stepper hiển thị 4 trạng thái trong Task Detail (loại Livestream).</li></ul><h2 id="_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" tabindex="-1">5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật) <a class="header-anchor" href="#_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" aria-label="Permalink to &quot;5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PATCH /api/v1/workspaces/{id}/tasks/{taskId}/livestream/status</span></span>
<span class="line"><span>{ &quot;status&quot;: &quot;pre_live|live|post_live|done|cancel&quot; }</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: { ...updated livestream status... } }</span></span></code></pre></div><h2 id="_6-error-handling" tabindex="-1">6. Error Handling <a class="header-anchor" href="#_6-error-handling" aria-label="Permalink to &quot;6. Error Handling&quot;">​</a></h2><ul><li>Chuyển trạng thái không hợp lệ (ví dụ từ DONE quay lại LIVE) → 409 <code>INVALID_LIVESTREAM_TRANSITION</code>.</li></ul><h2 id="_7-edge-cases" tabindex="-1">7. Edge Cases <a class="header-anchor" href="#_7-edge-cases" aria-label="Permalink to &quot;7. Edge Cases&quot;">​</a></h2><ul><li>Cancel ở POST_LIVE (đã live xong, đang xử lý hậu kỳ) → KHÔNG hợp lệ, chỉ Cancel được ở PRE_LIVE hoặc LIVE theo state machine đã xác nhận.</li></ul><h2 id="_8-definition-of-done" tabindex="-1">8. Definition of Done <a class="header-anchor" href="#_8-definition-of-done" aria-label="Permalink to &quot;8. Definition of Done&quot;">​</a></h2><ul><li>Chuyển trạng thái đúng theo state machine, chặn transition không hợp lệ.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Không có.</li></ul><h2 id="tham-chieu-ba" tabindex="-1">Tham chiếu BA <a class="header-anchor" href="#tham-chieu-ba" aria-label="Permalink to &quot;Tham chiếu BA&quot;">​</a></h2><p><a href="./../../../BA/05-content-task-workflow.html">05-content-task-workflow.md</a>, <a href="./../../../BA/12-state-machines.html">12-state-machines.md</a></p>`,22)])])}const m=a(n,[["render",o]]);export{p as __pageData,m as default};
